    const rows=bookings.filter(b=>{const status=String(b.status).toUpperCase(),matches=filter==='ALL'||(filter==='DECLINED'?status==='REJECTED':filter==='UPCOMING'?status==='APPROVED'&&b.event_date>=new Date().toLocaleDateString('sv-SE'):status===filter);return matches&&(!search||`${b.customer_name} ${b.email} ${b.event_type} ${b.package_name} ${b.id}`.toLowerCase().includes(search));});
