    const expenseRows=reportExpenses.map(e=>`<tr><td data-label="Date">${esc(dateLabel(e.expense_date))}</td><td data-label="Description"><strong>${esc(e.description)}</strong></td><td data-label="Amount">${peso(e.amount_cents)}</td><td data-label="Record"><span class="monthly-report-record-status">${e.archived_at?'Archived':'Recorded'}</span></td></tr>`).join('');
    modal(`<div class="monthly-activity-report"><div class="monthly-report-header"><span class="badge">MONTHLY REPORT</span><h3>${esc(monthLabel)} Activity</h3><p>Bookings and expenses recorded for this month.</p></div><div class="monthly-report-summary"><article><span>Event income</span><strong>${peso(income)}</strong></article><article><span>Expenses</span><strong>${peso(expenseTotal)}</strong></article><article><span>Net income</span><strong>${peso(income-expenseTotal)}</strong></article></div><section><div class="panel-head"><h4>Bookings (${reportBookings.length})</h4></div>${reportBookings.length?`<div class="table-wrap"><table class="monthly-report-booking-table"><thead><tr><th>Date & time</th><th>Client</th><th>Event</th><th>Status</th><th>Total</th><th>Paid</th></tr></thead><tbody>${bookingRows}</tbody></table></div>`:'<div class="empty-state">No approved bookings for this month.</div>'}</section><section><div class="panel-head"><h4>Expenses (${reportExpenses.length})</h4></div>${reportExpenses.length?`<div class="table-wrap"><table class="monthly-report-expense-table"><thead><tr><th>Date</th><th>Description</th><th>Amount</th><th>Record</th></tr></thead><tbody>${expenseRows}</tbody></table></div>`:'<div class="empty-state">No expenses for this month.</div>'}</section></div>`);
    $('#modal .modal-card')?.classList.add('monthly-activity-modal-card');
