  function paintFinance(selected,stats){paintSalesTable();month=selected;$('#salesAnalyticsMonth').value=selected;$('#salesAnalyticsMonthLabel').textContent=`Net income by month for ${selected.slice(0,4)}`;$('#salesMonthPickerTrigger').innerHTML=`${new Intl.DateTimeFormat('en-PH',{month:'long',year:'numeric'}).format(new Date(`${selected}-01T00:00:00`))} <span aria-hidden="true">▾</span>`;$('#salesMonthPickerYear').textContent=selected.slice(0,4);$('#salesMonthPickerMonths').innerHTML=Array.from({length:12},(_,i)=>`<button type="button" data-month-choice="${selected.slice(0,4)}-${String(i+1).padStart(2,'0')}">${new Intl.DateTimeFormat('en-PH',{month:'short'}).format(new Date(Number(selected.slice(0,4)),i,1))}</button>`).join('');$('#salesRevenue').textContent=peso(stats.month_income_cents);$('#salesExpenses').textContent=peso(stats.month_expenses_cents);$('#salesNet').textContent=peso(stats.month_net_cents);const byMonth=stats.monthly_finance,max=Math.max(1,...byMonth.map(v=>Math.abs(v.net_cents)));$('#monthlyNetIncomeChart').innerHTML=byMonth.map(item=>`<div class="monthly-net-column" title="${peso(item.net_cents)}"><span class="monthly-net-value">${peso(item.net_cents)}</span><span class="monthly-net-bar-track"><i class="monthly-net-bar${item.net_cents<0?' is-negative':''}" style="height:${Math.max(2,Math.abs(item.net_cents)/max*100)}%"></i></span><span class="monthly-net-month">${new Intl.DateTimeFormat('en-PH',{month:'short'}).format(new Date(Number(selected.slice(0,4)),item.month-1,1))}</span></div>`).join('');$('#monthlyNetIncomePeak').textContent=`Selected month net: ${peso(stats.month_net_cents)}`;const monthBookings=bookings.filter(b=>b.event_date.startsWith(selected)&&b.status==='approved').length,monthExpenses=[...expenses,...archivedExpenses].filter(e=>e.expense_date.startsWith(selected)).length;$('#monthlyEventsCount').textContent=`${monthBookings} ${monthBookings===1?'booking':'bookings'} · ${monthExpenses} ${monthExpenses===1?'expense':'expenses'}`;}
