  document.addEventListener('click',async event=>{const nav=event.target.closest('[data-section],[data-section-jump]');if(nav){event.preventDefault();setSection(nav.dataset.section||nav.dataset.sectionJump);if(nav.closest('#adminSidebarNav'))closeMobileNav();if(nav.hasAttribute('data-close-modal'))closeModal();return;}try{const actionMenu=event.target.closest('[data-booking-menu],[data-ocular-menu],[data-payment-menu]');if(actionMenu){toggleAdminActionMenu(event,actionMenu);return;}const viewBooking=event.target.closest('[data-booking-view]');if(viewBooking){const b=bookings.find(item=>Number(item.id)===Number(viewBooking.dataset.bookingView));if(b)viewBookingRecord(b);return;}const booking=event.target.closest('[data-booking]');if(booking){const[id,status]=booking.dataset.booking.split('|');await api('booking-status',{booking_id:Number(id),status},'PATCH');await reload();return;}const pay=event.target.closest('[data-pay]');if(pay){const[id,status]=pay.dataset.pay.split('|');await api('payment-status',{payment_id:Number(id),status},'PATCH');await reload();return;}const recordPayment=event.target.closest('[data-payment-record]');if(recordPayment){const b=bookings.find(item=>Number(item.id)===Number(recordPayment.dataset.paymentRecord));if(b)recordPaymentForm(b);return;}const viewChange=event.target.closest('[data-change-view]');if(viewChange){const c=changes.find(item=>Number(item.id)===Number(viewChange.dataset.changeView)),b=c&&bookings.find(item=>Number(item.id)===Number(c.booking_id));if(c){const requestedDate=c.event_date?new Intl.DateTimeFormat('en-PH',{dateStyle:'long'}).format(new Date(`${c.event_date}T12:00:00`)):'Date not set',[hour,minute]=String(c.event_time||'').split(':').map(Number),requestedTime=Number.isInteger(hour)&&Number.isInteger(minute)?new Intl.DateTimeFormat('en-PH',{hour:'numeric',minute:'2-digit'}).format(new Date(2000,0,1,hour,minute)):'Time not set',requestedSlot=String(c.slot||'').toLowerCase().replace(/^./,letter=>letter.toUpperCase());modal(`<section class="client-request-history"><header class="client-request-history-header"><span class="eyebrow">CUSTOMER REQUEST</span><h3>${c.type==='cancel'?'Cancellation':'Reschedule'} request</h3><p>${esc(c.customer_name||'Customer')} · ${esc(b?.event_type||'Event')}<br>Current booking: ${esc(b?.event_date||c.booking_date||'Date not set')}</p></header>${c.type==='reschedule'?`<div class="booking-change-reason booking-request-schedule"><strong>Requested schedule</strong><p>${esc(requestedDate)}</p><small>${esc(requestedSlot)} · ${esc(requestedTime)}</small></div>`:''}<div class="booking-change-reason"><strong>Customer reason</strong><p>${esc(c.reason||'No reason recorded')}</p></div></section>`);}return;}const change=event.target.closest('[data-change]');if(change){const[id,approve]=change.dataset.change.split('|');await api('change-status',{request_id:Number(id),approve:approve==='true'},'PATCH');await reload();return;}const ocularView=event.target.closest('[data-ocular-view]');if(ocularView){const item=inspections.find(row=>Number(row.id)===Number(ocularView.dataset.ocularView));if(item){const formatDateTime=value=>{if(!value)return 'Not recorded';const parsed=new Date(value);return Number.isNaN(parsed.getTime())?'Not recorded':new Intl.DateTimeFormat('en-PH',{dateStyle:'medium',timeStyle:'short'}).format(parsed);},inspectionDateTime=formatDateTime(item.inspection_date&&item.inspection_time?`${item.inspection_date}T${item.inspection_time}`:item.inspection_date),submittedAt=formatDateTime(item.created_at),address=String(item.venue_address||'').trim(),city=String(item.venue_city||'').trim(),normalizeLocation=value=>value.toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim(),cityAlreadyInAddress=city&&normalizeLocation(address).includes(normalizeLocation(city)),locationRows=[['Venue name',item.venue_name],['Address',address],...(!cityAlreadyInAddress?[['City / area',city]]:[])].filter(([,value])=>String(value||'').trim()).map(([label,value])=>`<div class="quotation-detail-row is-wide"><span>${label}</span><strong>${esc(value)}</strong></div>`).join('');modal(`<section><header class="ocular-request-header"><span class="eyebrow">OCULAR INSPECTION</span><h3>${esc(item.request_code)}</h3><p><strong>${esc(item.status.toUpperCase())}</strong> · ${esc(submittedAt)}</p></header><section class="ocular-detail-section"><h4>Customer and venue</h4><div class="quotation-detail-list"><div class="quotation-detail-row"><span>Customer</span><strong>${esc(item.customer_name||item.contact_name)}</strong></div><div class="quotation-detail-row"><span>Contact</span><strong>${esc(item.email)} · ${esc(item.phone)}</strong></div>${locationRows}<div class="quotation-detail-row"><span>Inspection time</span><strong>${esc(inspectionDateTime)}</strong></div><div class="quotation-detail-row"><span>Distance and fee</span><strong>${Number(item.distance_km).toFixed(1)} km · ${peso(item.fee_cents)}</strong></div><div class="quotation-detail-row is-wide"><span>Payment reference</span><strong>${esc(item.payment_reference||'Not provided')}</strong></div><div class="quotation-detail-row is-wide"><span>Admin notes</span><strong>${esc(item.admin_notes||'None')}</strong></div></div></section></section>`);$('#modal .modal-card')?.classList.add('ocular-request-modal-card');}return;}const ocular=event.target.closest('[data-ocular]');if(ocular){const[id,status]=ocular.dataset.ocular.split('|');await api('ocular',{inspection_id:Number(id),status,admin_notes:prompt('Optional note for customer:')||''},'PATCH');await reload();return;}if(event.target.closest('#logoutBtn')){modal(`<div class="logout-confirmation"><span class="logout-confirmation-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M10 4H5.5A1.5 1.5 0 0 0 4 5.5v13A1.5 1.5 0 0 0 5.5 20H10M14 8l4 4-4 4M8 12h10"></path></svg></span><h3>Sign out of admin?</h3><p>You will need to sign in again to manage KQ Event Styling.</p><div class="modal-actions"><button type="button" class="small-btn" id="cancelLogoutBtn">Stay signed in</button><button type="button" class="btn danger" id="confirmLogoutBtn">Sign out</button></div></div>`);$('#modal .modal-card')?.classList.add('logout-confirmation-card');$('#cancelLogoutBtn').addEventListener('click',()=>closeModal());$('#confirmLogoutBtn').addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;button.textContent='Signing out…';try{await api('logout',{});location.href='login.html';}catch(error){button.disabled=false;button.textContent='Sign out';alert(error.message);}});return;}if(event.target.closest('#settingsMenuBtn')){const menu=$('#sidebarAccountMenu');menu.hidden=!menu.hidden;$('#settingsMenuBtn').setAttribute('aria-expanded',String(!menu.hidden));return;}if(event.target.closest('#editAccountBtn')){accountForm();return;}if(event.target.closest('#adminNotificationBtn')){const panel=$('#adminNotificationPanel');panel.hidden=!panel.hidden;$('#adminNotificationBtn').setAttribute('aria-expanded',String(!panel.hidden));return;}if(event.target.closest('#closeAdminNotifications')){$('#adminNotificationPanel').hidden=true;$('#adminNotificationBtn').setAttribute('aria-expanded','false');return;}if(event.target.closest('#modalClose')||event.target.closest('[data-close-modal]')){closeModal();return;}if(event.target.closest('#addExpenseBtn')){expenseForm();return;}if(event.target.closest('#addInventoryBtn')){inventoryForm();return;}const editStock=event.target.closest('[data-stock-edit]');if(editStock){inventoryForm(inventory.find(i=>Number(i.id)===Number(editStock.dataset.stockEdit)));return;}const removeStock=event.target.closest('[data-stock-delete]');if(removeStock&&confirm('Delete this material?')){await api('inventory',{inventory_id:Number(removeStock.dataset.stockDelete)},'DELETE');await reload();return;}const editExpense=event.target.closest('[data-expense-edit]');if(editExpense){expenseForm(expenses.find(i=>Number(i.id)===Number(editExpense.dataset.expenseEdit)));return;}const archiveExpense=event.target.closest('[data-expense-archive]');if(archiveExpense&&confirm('Move this expense to the archive?')){await api('expense-archive',{expense_id:Number(archiveExpense.dataset.expenseArchive),archived:true},'PATCH');await reload();return;}const restoreExpense=event.target.closest('[data-expense-restore]');if(restoreExpense){await api('expense-archive',{expense_id:Number(restoreExpense.dataset.expenseRestore),archived:false},'PATCH');await reload();return;}const pick=event.target.closest('[data-month-choice]');if(pick){$('#salesAnalyticsMonth').value=pick.dataset.monthChoice;$('#salesMonthPickerPopover').hidden=true;await renderFinance();return;}const step=event.target.closest('[data-sales-year-step]');if(step){const year=Number($('#salesAnalyticsMonth').value.slice(0,4)||new Date().getFullYear())+Number(step.dataset.salesYearStep);$('#salesAnalyticsMonth').value=`${year}-${month.slice(5)}`;await renderFinance();return;}if(event.target.closest('#salesMonthPickerTrigger')){$('#salesMonthPickerPopover').hidden=!$('#salesMonthPickerPopover').hidden;return;}if(event.target.closest('#monthlyActivityView')){openMonthlyActivityReport();return;}if(event.target.closest('#calendarBtn')){renderAdminCalendar('booking');return;}if(event.target.closest('#ocularCalendarBtn')){renderAdminCalendar('ocular');return;}}catch(error){showAdminError(error);}});
  $('#refreshBookingChangeRequests')?.addEventListener('click',async event=>{
    const button=event.currentTarget;if(button.disabled)return;
    const label=button.textContent;button.disabled=true;button.textContent='Refreshing…';button.setAttribute('aria-busy','true');
    try{changes=await api('changes');paintChanges();}
    catch(error){alert(error.message);}
    finally{button.disabled=false;button.textContent=label;button.removeAttribute('aria-busy');}
  });
  $('#bookingSearch')?.addEventListener('input',paintBookings);$('#bookingStatusFilter')?.addEventListener('change',paintBookings);$('#paymentStatusFilter')?.addEventListener('change',paintPayments);$('#quotationSearch')?.addEventListener('input',paintInspections);$('#quotationStatusFilter')?.addEventListener('change',paintInspections);
  document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeModal();closeMobileNav();}});
